api.look('blueprint');
const cx = api.w/2, top = 200, bot = 500;
const k = api.seg(t, 0, 1.2);
api.rect(cx-90, top-40, 180, 400, {c:'fg', w:4, k});
const py = api.lerp(top+120, bot-60, 0.5 + 0.5*Math.sin(t*2));
api.rect(cx-86, py, 172, 40, {c:'accent', fill:'accent', w:3, k});
api.line(cx, py+40, cx, 640, {c:'fg', w:5, k});
api.circle(cx, 680, 36, {c:'a2', w:4, k});
api.text('Piston', cx+130, py+20, {size:20, c:'accent', k:api.seg(t,1,2)});
api.text('Crank', cx+110, 690, {size:20, c:'a2', k:api.seg(t,1.4,2.4)});
api.say('One cylinder, four strokes', 0.3, 3.5);

api.look('blueprint');
const cx = api.w/2, top = 200;
const k = api.seg(t, 0, 1);
api.rect(cx-90, top-40, 180, 400, {c:'fg', w:4});
const py = api.lerp(top-10, top+250, api.ease(api.seg(t,0.5,4)));
api.rect(cx-86, py, 172, 40, {c:'accent', fill:'accent', w:3});
api.line(cx, py+40, cx, 640, {c:'fg', w:5});
api.circle(cx, 680, 36, {c:'a2', w:4});
api.line(cx-60, top-40, cx-60, top-90, {c:'a2', w:6});
api.arrow(cx-60, top-130, cx-60, top-50, {c:'a2', w:4, k:api.seg(t,0.3,1.5)});
api.swarm(40, t, {mode:'fall', cx:cx, cy:top+60, rx:70, ry:90, c:'a2', size:3});
api.label('1  Intake', cx, 120, {k});
api.say('Piston drops, air flows in', 0.3, 4.5);

api.look('blueprint');
const cx = api.w/2, top = 200;
api.rect(cx-90, top-40, 180, 400, {c:'fg', w:4});
api.line(cx-90, top-40, cx+90, top-40, {c:'fg', w:8});
const e = api.ease(api.seg(t,0.3,3.5));
const py = api.lerp(top+250, top+10, e);
api.rect(cx-86, py, 172, 40, {c:'accent', fill:'accent', w:3});
api.line(cx, py+40, cx, 640, {c:'fg', w:5});
api.circle(cx, 680, 36, {c:'a2', w:4});
const h = py - (top-40);
api.rect(cx-86, top-38, 172, h, {c:'a2', fill:'a2', a:0.15+0.4*e, w:0});
api.arrow(cx, py+90, cx, py+50, {c:'accent', w:5, k:api.seg(t,0.5,1.5)});
api.label('2  Compression', cx, 120, {k:api.seg(t,0,0.8)});
api.say('Piston squeezes the mix', 0.3, 4.5);

api.look('blueprint');
const cx = api.w/2, top = 200;
const e = api.ease(api.seg(t,1,4.5));
const py = api.lerp(top+10, top+250, e);
const sp = api.seg(t,0.2,1);
api.rect(cx-90, top-40, 180, 400, {c:'fg', w:4});
api.line(cx-90, top-40, cx+90, top-40, {c:'fg', w:8});
api.rect(cx-86, top-38, 172, py-top+38, {c:'warn', fill:'warn', a:0.5*(1-e*0.6), w:0});
api.rect(cx-86, py, 172, 40, {c:'accent', fill:'accent', w:3});
api.line(cx, py+40, cx, 640, {c:'fg', w:5});
api.circle(cx, 680, 36, {c:'a2', w:4});
api.shape('bolt', cx, top+30, 70+40*api.pulse(t,3), {c:'warn', k:sp});
api.glow(cx, top+30, 100*sp, {c:'warn'});
api.arrow(cx, py+60, cx, py+130, {c:'accent', w:6, k:api.seg(t,1.5,2.5)});
api.label('3  Power', cx, 120, {k:api.seg(t,0,0.8)});
api.say('Spark burns, piston is pushed', 0.3, 5.5);

api.look('blueprint');
const cx = api.w/2, top = 200;
const e = api.ease(api.seg(t,0.4,3.5));
const py = api.lerp(top+250, top+10, e);
api.rect(cx-90, top-40, 180, 400, {c:'fg', w:4});
api.rect(cx-86, py, 172, 40, {c:'accent', fill:'accent', w:3});
api.line(cx, py+40, cx, 640, {c:'fg', w:5});
api.circle(cx, 680, 36, {c:'a2', w:4});
api.line(cx+60, top-40, cx+60, top-90, {c:'dim', w:6});
api.arrow(cx+60, top-60, cx+60, top-140, {c:'dim', w:4, k:api.seg(t,0.4,1.5)});
api.swarm(40, t, {mode:'rise', cx:cx+60, cy:top-60, rx:30, ry:100, c:'dim', size:4});
api.label('4  Exhaust', cx, 120, {k:api.seg(t,0,0.8)});
api.say('Piston pushes smoke out', 0.3, 5.5);

api.look('blueprint');
const cx = api.w/2, cy = 380, r = 130;
const names = ['Intake','Compress','Power','Exhaust'];
const cols = ['a2','a3','warn','dim'];
const ph = Math.floor(t/1.1) % 4;
for (let i=0;i<4;i++){
  const a0 = -Math.PI/2 + i*Math.PI/2 + 0.08, a1 = a0 + Math.PI/2 - 0.16;
  api.arc(cx, cy, r, a0, a1, {c:cols[i], w: i===ph?16:8, k:api.seg(t, i*0.25, i*0.25+0.5)});
  const am = (a0+a1)/2;
  api.text(names[i], cx+Math.cos(am)*(r+60), cy+Math.sin(am)*(r+60), {size:18, c:cols[i], align:'center', k:api.seg(t,i*0.25+0.3,i*0.25+0.8)});
}
const a = -Math.PI/2 + t*(Math.PI/2)/1.1;
api.dot(cx+Math.cos(a)*r, cy+Math.sin(a)*r, 12, {c:'accent'});
api.kinetic('Repeat', cx, cy+4, {mode:'pop', size:34, k:api.seg(t,1,2)});
api.say('Four strokes, then again', 0.3, 4.5);
